# Classes and objects as Platonic ideals
class Book:
    def __init__(self, title, author, year=None):
        self.title = title
        self.author = author
        self.year = year
        self._reviews = []  # Encapsulated implementation detail

    def add_review(self, text, rating):
        self._reviews.append({"text": text, "rating": rating})

    @property
    def average_rating(self):
        if not self._reviews:
            return None
        return sum(review["rating"] for review in self._reviews) / len(self._reviews)

    def __str__(self):
        return f"\"{self.title}\" by {self.author}"

# Inheritance creating specialized types
class Ebook(Book):
    def __init__(self, title, author, year=None, format="PDF"):
        super().__init__(title, author, year)
        self.format = format
        self.file_size = None

    def download(self):
        return f"Downloading {self.title} as {self.format}..."

    def __str__(self):
        return f"\"{self.title}\" by {self.author} ({self.format})"

class AudioBook(Book):
    def __init__(self, title, author, year=None, narrator=None, duration=None):
        super().__init__(title, author, year)
        self.narrator = narrator
        self.duration = duration

    def play(self):
        return f"Playing {self.title}, narrated by {self.narrator}"

    def __str__(self):
        base = super().__str__()
        return f"{base}, narrated by {self.narrator}"

# Polymorphism through a common interface
def read_book(book):
    print(f"Reading {book}")  # Will use each class's __str__ method
    # All book types can be "read" despite different implementations

# Encapsulation through controlled interfaces
class Library:
    def __init__(self, name):
        self.name = name
        self._books = {}  # Private implementation detail
        self._last_id = 0

    def add_book(self, book):
        self._last_id += 1
        self._books[self._last_id] = book
        return self._last_id

    def get_book(self, book_id):
        return self._books.get(book_id)

    def remove_book(self, book_id):
        if book_id in self._books:
            del self._books[book_id]
            return True
        return False

    @property
    def book_count(self):
        return len(self._books)

# Demonstrating our object model
library = Library("Great Books Collection")

moby_dick = Book("Moby-Dick", "Herman Melville", 1851)
moby_dick.add_review("A masterpiece of American literature", 5)
moby_dick.add_review("Too much whale anatomy", 3)
print(f"{moby_dick} - Average rating: {moby_dick.average_rating}")

digital_fortress = Ebook("Digital Fortress", "Dan Brown", 1998, "EPUB")
print(digital_fortress.download())

sherlock = AudioBook("The Adventures of Sherlock Holmes", "Arthur Conan Doyle", 1892, "Stephen Fry", "10:50:00")
print(sherlock.play())

# Polymorphic behavior
for book in [moby_dick, digital_fortress, sherlock]:
    read_book(book)
    book_id = library.add_book(book)
    print(f"Added to library with ID: {book_id}")

print(f"Library now contains {library.book_count} books")
